    logic        [                             7:0] q [0:7];
    //reg signed [2+FRACTIONAL_WIDTH-1:0] Q [0:7];
    logic signed [                 INPUT_WIDTH-1:0] i [0:7];
    logic signed [INPUT_WIDTH+FRACTIONAL_WIDTH-1:0] O [0:7];
    logic signed [            (8*OUTPUT_WIDTH)-1:0] o; /// [0:7];

    ///
    assign q = {qi[0],qi[1],qi[2],qi[3],qi[4],qi[5],qi[6],qi[7]};
    ///
    assign i = {in[0],in[1],in[2],in[3],in[4],in[5],in[6],in[7]};
    ///
    assign {ou[7],ou[6],ou[5],ou[4],ou[3],ou[2],ou[1],ou[0]}=o;


    genvar m;
    generate 
        for(m=0;m<8;m=m+1) begin :gen21
            assign O[m]=(|q[m])?($signed(i[m])*Q[q[m]]):($signed(i[m])>>>(INPUT_WIDTH-OUTPUT_WIDTH));                 
            assign o[(m+1)*OUTPUT_WIDTH-1:m*OUTPUT_WIDTH]=(O[m]+(1<<(FRACTIONAL_WIDTH+INPUT_WIDTH-OUTPUT_WIDTH-1)))>>>(FRACTIONAL_WIDTH+INPUT_WIDTH-OUTPUT_WIDTH);
        end
    endgenerate
